window.__votdWeek && window.__votdWeek({"week":"2028-07-17","reading":"Alma 32–35","days":[{"d":"2028-07-17","ref":"Alma 32:6","b":"Alma","c":32,"v":6,"he":"וַיְהִי כִּשְׁמֹעַ אַלְמָא אֶת־זֹאת וַיִּסֹּב אֶת־פָּנָיו אֵלָיו פִּתְאֹם וַיַּרְא בְּשִׂמְחָה גְדוֹלָה כִּי רָאָה כִּי צָרוֹתֵיהֶם הִכְנִיעוּם בֶּאֱמֶת וְכִי נָכוֹנוּ לִשְׁמֹעַ אֶת־הַדָּבָר׃","en":"And now when Alma heard this, he turned him about, his face immediately towards him, and he beheld with great joy; for he beheld that their afflictions had truly humbled them, and that they were in a preparation to hear the word."},{"d":"2028-07-18","ref":"Alma 32:23","b":"Alma","c":32,"v":23,"he":"וְעַתָּה יְחַלֵּק אֶת־דְּבָרוֹ בְּיַד מַלְאָכִים לַאֲנָשִׁים אַף לֹא־רַק לַאֲנָשִׁים כִּי־אִם גַּם לַנָּשִׁים וְלֹא זֹאת בִּלְבָד גַּם לַיְלָדִים הַקְּטַנִּים נִתְּנוּ דְבָרִים פְּעָמִים רַבּוֹת הַמְסַכְּלִים אֶת־הַחֲכָמִים וְהַמְּלֻמָּדִים׃","en":"And now, he imparteth his word by angels unto men, yea, not only men but women also. Now this is not all; little children do have words given unto them many times, which confound the wise and the learned."},{"d":"2028-07-19","ref":"Alma 33:7","b":"Alma","c":33,"v":7,"he":"וְכַאֲשֶׁר שַׁבְתִּי אֶל חֶדְרִי יְהוָה וָאֶתְפַּלֵּל אֵלֶיךָ שָׁמַעְתָּ אוֹתִי׃","en":"And when I did turn unto my closet, O Lord, and prayed unto thee, thou didst hear me."},{"d":"2028-07-20","ref":"Alma 33:19","b":"Alma","c":33,"v":19,"he":"הִנֵּה דִּבֶּר עָלָיו מֹשֶׁה וְהִנֵּה הוּרַם דְּמוּת בַּמִּדְבָּר לְמַעַן כׇּל הַמַּבִּיט אֵלָיו יִחְיֶה וְרַבִּים הִבִּיטוּ וַיִּחְיוּ׃","en":"Behold, he was spoken of by Moses; yea, and behold a type was raised up in the wilderness, that whosoever would look upon it might live. And many did look and live."},{"d":"2028-07-21","ref":"Alma 34:9","b":"Alma","c":34,"v":9,"he":"כִּי נָכוֹן לַעֲשׂוֹת כַּפָּרָה כִּי כְּפִי עֲצַת אֵל עוֹלָם הַגְּדוֹלָה תֵּעָשֶׂה כַּפָּרָה וְאִם־לֹא יֹאבַד כׇּל הָאָדָם בְּאֵין מָנוֹס אַף הַכֹּל קְשֵׁי־עֹרֶף אַף הַכֹּל נָפְלוּ וְאָבְדוּ וְיֹאבְדוּ כִּי־אִם בַּכַּפָּרָה אֲשֶׁר נָכוֹן לַעֲשׂוֹת׃","en":"For it is expedient that an atonement should be made; for according to the great plan of the Eternal God there must be an atonement made, or else all mankind must unavoidably perish; yea, all are hardened; yea, all are fallen and are lost, and must perish except it be through the atonement which it is expedient should be made."},{"d":"2028-07-22","ref":"Alma 34:10","b":"Alma","c":34,"v":10,"he":"כִּי נָכוֹן לִהְיוֹת זֶבַח גָּדוֹל וְאַחֲרוֹן אַף לֹא זֶבַח אָדָם וְלֹא זֶבַח בְּהֵמָה וְלֹא כׇל מִין עוֹף כִּי־לֹא יִהְיֶה זֶבַח אָדָם אַךְ יִהְיֶה זֶבַח אֵין־קֵץ וְעוֹלָם׃","en":"For it is expedient that there should be a great and last sacrifice; yea, not a sacrifice of man, neither of beast, neither of any manner of fowl; for it shall not be a human sacrifice; but it must be an infinite and eternal sacrifice."},{"d":"2028-07-23","ref":"Alma 35:10","b":"Alma","c":35,"v":10,"he":"וְעַתָּה זֹאת הֵעִירָה אֶת־חֲמַת הַזּוֹרָמִים נֶגֶד עַם עַמּוֹן וַיָּחֵלּוּ לְהִתְעָרֵב עִם־הַלָּמָנִים וּלְהָעִיר גַּם אוֹתָם לַחֲרוֹת אַף נֶגְדָּם׃","en":"Now this did stir up the Zoramites to anger against the people of Ammon, and they began to mix with the Lamanites and to stir them up also to anger against them."}]});
